\text{Vector Space axioms} \\
\begin{align*}
\mathbf{u} + \mathbf{v} &= \mathbf{v} + \mathbf{u} \quad \text{(Commutativity)} \\
(\mathbf{u} + \mathbf{v}) + \mathbf{w} &= \mathbf{u} + (\mathbf{v} + \mathbf{w}) \quad \text{(Associativity)} \\
\exists \mathbf{0} \in V \text{ such that } \mathbf{u} + \mathbf{0} &= \mathbf{u} \\
\exists -\mathbf{u} \text{ such that } \mathbf{u} + (-\mathbf{u}) &= \mathbf{0}
\end{align*}
