\begin{aligned}
\|A\|_2 &= \sqrt{\lambda_{\max}(A^T A)} = \sigma_{\max}(A) \quad &\text{(spectral norm)} \\
\|A\|_F &= \sqrt{\sum_{i=1}^m \sum_{j=1}^n |a_{ij}|^2} = \sqrt{\sum_{i=1}^r \sigma_i^2} \quad &\text{(Frobenius norm)} \\
\|A\|_1 &= \max_{1 \leq j \leq n} \sum_{i=1}^m |a_{ij}| \quad &\text{(column sum)} \\
\|A\|_\infty &= \max_{1 \leq i \leq m} \sum_{j=1}^n |a_{ij}| \quad &\text{(row sum)}
\end{aligned}
